gczR(){return"\u0622\u0641\u0633\u062a \u0647\u0631 \u0627\u0631\u0632"},
gczQ(){return"\u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0628\u0627 \u0645\u0642\u0627\u062f\u06cc\u0631 \u0641\u0639\u0644\u06cc \u0641\u0631\u0645 (\u067e\u06cc\u0634\u200c\u0646\u0648\u06cc\u0633) \u0645\u062d\u0627\u0633\u0628\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0628\u0631\u0627\u06cc \u0645\u0627\u0646\u062f\u06af\u0627\u0631\u06cc\u060c \u0630\u062e\u06cc\u0631\u0647 \u06a9\u0646\u06cc\u062f."},
gczW(){return"\u062a\u0627\u0632\u0647\u200c\u0633\u0627\u0632\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634"},
gczH(){return"\u0627\u0631\u0632 \u0641\u0631\u0639\u06cc\u200c\u0627\u06cc \u06cc\u0627\u0641\u062a \u0646\u0634\u062f."},
